// 来源：beUI <https://beui.dev/r/liquidity-heatmap.json>，上游文件 components/charts/liquidity-heatmap.tsx
// 许可证：MIT © 2026 Saurabh Chauhan <https://github.com/starc007/ui-components/blob/main/LICENSE>
