"use client";
// beui.dev/charts/liquidity-heatmap

import { createContext, useContext, useId, useMemo, useRef, useState, type ReactNode } from "react";
import { motion, useReducedMotion } from "motion/react";
import { NumberTicker } from "@/components/vendor/beui/motion/number-ticker";
import { Tooltip } from "@/components/vendor/beui/motion/tooltip";
import { EASE_OUT } from "@/components/vendor/beui/lib/ease";
import { cn } from "@/lib/utils";
import {
  buildLiquidityHeatmap,
  pricePosition,
  type LiquiditySnapshot,
} from "./liquidity-heatmap/model";

const formatPrice = (value: number) => value.toLocaleString("en-US", { maximumFractionDigits: 2 });
const formatSize = (value: number) =>
  value.toLocaleString("en-US", { notation: "compact", maximumFractionDigits: 1 });
const colors = ["#17233b", "#254f80", "#217c90", "#27af98", "#97d56b", "#f4df76"];
function heatColor(value: number, max: number) {
  return colors[
    Math.min(colors.length - 1, Math.floor((max > 0 ? value / max : 0) * colors.length))
  ];
}
interface LiquidityHeatmapProps {
  /** Time-ordered snapshots; use consistent price buckets and stable IDs. */
  snapshots: readonly LiquiditySnapshot[];
  /** Fixed intensity ceiling keeps colors comparable across live updates. */
  maxSize?: number;
  unit?: string;
  label?: string;
  formatPrice?: (price: number) => string;
  formatSize?: (size: number) => string;
  children?: ReactNode;
  className?: string;
}
const Context = createContext<
  | (ReturnType<typeof buildLiquidityHeatmap> & {
      ceiling: number;
      unit: string;
      formatPrice: (value: number) => string;
      formatSize: (value: number) => string;
    })
  | null
>(null);
export function useLiquidityHeatmap() {
  const value = useContext(Context);
  if (!value) throw new Error("Liquidity heatmap parts must be inside LiquidityHeatmap");
  return value;
}
export function LiquidityHeatmap({
  snapshots,
  maxSize,
  unit = "units",
  label = "Liquidity heatmap",
  formatPrice: priceFormatter = formatPrice,
  formatSize: sizeFormatter = formatSize,
  children,
  className,
}: LiquidityHeatmapProps) {
  const model = useMemo(() => buildLiquidityHeatmap(snapshots), [snapshots]);
  const ceiling =
    maxSize !== undefined && Number.isFinite(maxSize) && maxSize > 0 ? maxSize : model.maximum;
  return (
    <Context.Provider
      value={{ ...model, ceiling, unit, formatPrice: priceFormatter, formatSize: sizeFormatter }}
    >
      <section aria-label={label} className={cn("w-full space-y-4", className)}>
        {children ?? (
          <>
            <LiquidityHeatmapPlot />
            <LiquidityHeatmapLegend />
          </>
        )}
      </section>
    </Context.Provider>
  );
}

export function LiquidityHeatmapPlot({ className }: { className?: string }) {
  const { columns, prices, ceiling, unit, formatPrice, formatSize } = useLiquidityHeatmap();
  const reduced = useReducedMotion();
  const root = useRef<HTMLDivElement>(null);
  const anchor = useRef<HTMLButtonElement>(null);
  const tooltipId = useId();
  const [active, setActive] = useState<string | null>(null);
  const [cursor, setCursor] = useState<string | null>(null);
  const keys = prices.flatMap((price) =>
    columns.map((column) => JSON.stringify([column.id, price])),
  );
  const validCursor = cursor !== null && keys.includes(cursor) ? cursor : keys[0];
  if (cursor !== null && !keys.includes(cursor)) setCursor(null);
  if (active !== null && !keys.includes(active)) setActive(null);
  const activeIndex = active === null ? -1 : keys.indexOf(active);
  const row = Math.floor(activeIndex / columns.length);
  const col = activeIndex % columns.length;
  const selected = activeIndex >= 0 ? columns[col] : null;
  const size = selected?.levels.get(prices[row]);
  let connected = false;
  const path = columns
    .map((column, index) => {
      const y = column.price === undefined ? null : pricePosition(column.price, prices);
      if (y === null) {
        connected = false;
        return "";
      }
      const command = connected ? "L" : "M";
      connected = true;
      return `${command}${index + 0.5},${y}`;
    })
    .join(" ");
  if (!prices.length || !columns.length)
    return (
      <p className={cn("py-16 text-center text-sm text-muted-foreground", className)}>
        No liquidity data
      </p>
    );
  return (
    <div className={cn("overflow-x-auto", className)} ref={root}>
      <div
        className="relative"
        style={{ minWidth: Math.max(480, columns.length * 24), paddingRight: 72 }}
      >
        <div className="relative">
          <table
            aria-label="Liquidity by price and time"
            className="w-full table-fixed border-separate border-spacing-[2px]"
          >
            <thead className="sr-only">
              <tr>
                {columns.map((column) => (
                  <th key={column.id} scope="col">
                    {column.label}
                  </th>
                ))}
              </tr>
            </thead>
            <tbody>
              {prices.map((price, rowIndex) => (
                <tr key={price}>
                  {columns.map((column, columnIndex) => {
                    const value = column.levels.get(price);
                    const key = JSON.stringify([column.id, price]);
                    const index = rowIndex * columns.length + columnIndex;
                    return (
                      <td key={column.id} className="p-0">
                        <button
                          type="button"
                          data-cell={index}
                          tabIndex={key === validCursor ? 0 : -1}
                          aria-label={`${column.label}, ${formatPrice(price)}: ${value === undefined ? "No data" : `${formatSize(value)} ${unit}`}`}
                          aria-describedby={key === active ? tooltipId : undefined}
                          className="relative block h-6 w-full rounded-[2px] bg-muted/30 outline-none focus-visible:ring-2 focus-visible:ring-foreground focus-visible:z-10"
                          onPointerEnter={(event) => {
                            if (event.pointerType !== "touch") {
                              anchor.current = event.currentTarget;
                              setActive(key);
                            }
                          }}
                          onPointerLeave={() => setActive(null)}
                          onFocus={(event) => {
                            anchor.current = event.currentTarget;
                            setCursor(key);
                            setActive(key);
                          }}
                          onBlur={() => setActive(null)}
                          onClick={(event) => {
                            anchor.current = event.currentTarget;
                            setActive(key);
                          }}
                          onKeyDown={(event) => {
                            if (event.key === "Escape") {
                              setActive(null);
                              return;
                            }
                            const offsets: Record<string, number> = {
                              ArrowRight: 1,
                              ArrowLeft: -1,
                              ArrowDown: columns.length,
                              ArrowUp: -columns.length,
                              Home: -columnIndex,
                              End: columns.length - 1 - columnIndex,
                            };
                            if (!(event.key in offsets)) return;
                            event.preventDefault();
                            const next = Math.max(
                              0,
                              Math.min(keys.length - 1, index + offsets[event.key]),
                            );
                            root.current
                              ?.querySelector<HTMLButtonElement>(`[data-cell="${next}"]`)
                              ?.focus();
                          }}
                        >
                          <motion.span
                            aria-hidden="true"
                            className="pointer-events-none absolute inset-0 rounded-[2px]"
                            initial={false}
                            animate={{
                              opacity: value === undefined ? 0 : 1,
                              backgroundColor: heatColor(value ?? 0, ceiling),
                            }}
                            transition={{ duration: 0.28, ease: EASE_OUT }}
                          />
                          {key === active && (
                            <span
                              aria-hidden="true"
                              className="pointer-events-none absolute inset-0 rounded-[2px] ring-1 ring-inset ring-white"
                            />
                          )}
                        </button>
                      </td>
                    );
                  })}
                </tr>
              ))}
            </tbody>
          </table>
          <div
            aria-hidden="true"
            className="absolute -right-[72px] top-0 bottom-0 flex w-16 flex-col justify-around text-right font-mono text-[10px] tabular-nums text-muted-foreground"
          >
            {prices.map((price) => (
              <span key={price}>{formatPrice(price)}</span>
            ))}
          </div>
          {/* Remount only when trace topology changes; numeric coordinates otherwise interpolate together. */}
          <svg
            key={columns
              .map(
                (column) =>
                  `${column.id}:${column.price !== undefined && pricePosition(column.price, prices) !== null}`,
              )
              .join("|")}
            aria-hidden="true"
            className="pointer-events-none absolute inset-0 h-full w-full overflow-visible"
            viewBox={`0 0 ${columns.length} ${prices.length}`}
            preserveAspectRatio="none"
          >
            <motion.path
              initial={false}
              animate={{ d: path }}
              transition={{ duration: reduced ? 0 : 0.28, ease: EASE_OUT }}
              fill="none"
              stroke="black"
              strokeOpacity="0.35"
              strokeWidth="4"
              vectorEffect="non-scaling-stroke"
            />
            <motion.path
              initial={false}
              animate={{ d: path }}
              transition={{ duration: reduced ? 0 : 0.28, ease: EASE_OUT }}
              fill="none"
              stroke="white"
              strokeOpacity="0.9"
              strokeWidth="1.5"
              strokeLinejoin="round"
              vectorEffect="non-scaling-stroke"
            />
          </svg>
        </div>
        <div
          aria-hidden="true"
          className="mt-3 flex justify-between font-mono text-[10px] text-muted-foreground"
        >
          {columns
            .filter(
              (_, index) =>
                index % Math.max(1, Math.ceil(columns.length / 5)) === 0 ||
                index === columns.length - 1,
            )
            .map((column) => (
              <span key={column.id}>{column.label}</span>
            ))}
        </div>
      </div>
      <Tooltip
        key={active ?? "closed"}
        id={tooltipId}
        open={selected !== null}
        anchorRef={anchor}
        onOpenChange={(open) => {
          if (!open) setActive(null);
        }}
        content={
          selected && (
            <span className="flex flex-col gap-1 font-mono text-xs">
              <span className="text-muted-foreground">
                {selected.label} · {formatPrice(prices[row])}
              </span>
              <span className="inline-flex items-center tabular-nums">
                {size === undefined ? "No data" : (
                  <NumberTicker
                    value={size}
                    // Format the original amount so fractional liquidity is preserved.
                    format={() => formatSize(size)}
                    suffix={` ${unit}`}
                    duration={0.35}
                    startOnView={false}
                  />
                )}
              </span>
              {selected.price !== undefined && Number.isFinite(selected.price) && (
                <span className="text-muted-foreground">Market {formatPrice(selected.price)}</span>
              )}
            </span>
          )
        }
      />
    </div>
  );
}

export function LiquidityHeatmapLegend({ className }: { className?: string }) {
  const { ceiling, formatSize, unit } = useLiquidityHeatmap();
  return (
    <div
      className={cn(
        "flex flex-wrap items-center justify-between gap-3 text-[10px] text-muted-foreground",
        className,
      )}
    >
      <span>Resting liquidity · {unit}</span>
      <span className="flex items-center gap-2">
        <span>0</span>
        <span aria-hidden="true" className="flex gap-0.5">
          {colors.map((color) => (
            <span
              key={color}
              className="h-2 w-5 rounded-[1px]"
              style={{ backgroundColor: color }}
            />
          ))}
        </span>
        <span>{formatSize(ceiling)}+</span>
      </span>
    </div>
  );
}
export type { LiquiditySnapshot, LiquidityHeatmapProps };

// 收录组件 · developstack 设计系统（ADR 0016）：原样收录，勿手改；同步上游时整文件覆盖。
// 来源：beUI <https://beui.dev/r/liquidity-heatmap.json>，上游文件 components/charts/liquidity-heatmap/model.ts
// 许可证：MIT © 2026 Saurabh Chauhan <https://github.com/starc007/ui-components/blob/main/LICENSE>
// 收录：2026-10-04；适配：落点（明细见 vendor.lock.json）
export interface LiquiditySnapshot {
  /** Stable identity, usually an ISO timestamp. */
  id: string;
  label: string;
  levels: readonly { price: number; size: number }[];
  price?: number;
}

/** Invalid observations are omitted; zero size is distinct from missing data. */
export function buildLiquidityHeatmap(snapshots: readonly LiquiditySnapshot[]) {
  const seen = new Set<string>();
  const columns = snapshots
    .filter((snapshot) => {
      if (seen.has(snapshot.id)) return false;
      seen.add(snapshot.id);
      return true;
    })
    .map((snapshot) => {
      const levels = new Map<number, number>();
      for (const { price, size } of snapshot.levels) {
        if (!Number.isFinite(price) || price <= 0 || !Number.isFinite(size) || size < 0) continue;
        const total = (levels.get(price) ?? 0) + size;
        if (Number.isFinite(total)) levels.set(price, total);
      }
      return { ...snapshot, levels };
    });
  const prices = [...new Set(columns.flatMap((column) => [...column.levels.keys()]))].sort(
    (a, b) => b - a,
  );
  let maximum = 0;
  for (const column of columns)
    for (const size of column.levels.values()) maximum = Math.max(maximum, size);
  return { columns, prices, maximum };
}

/** Price levels are discrete bands; interpolate the trace between their centers. */
export function pricePosition(price: number, prices: readonly number[]) {
  if (
    !Number.isFinite(price) ||
    !prices.length ||
    price > prices[0] ||
    price < prices[prices.length - 1]
  )
    return null;
  for (let index = 0; index < prices.length - 1; index++) {
    if (price <= prices[index] && price >= prices[index + 1]) {
      return index + 0.5 + (prices[index] - price) / (prices[index] - prices[index + 1]);
    }
  }
  return prices.length - 0.5;
}

// 收录组件 · developstack 设计系统（ADR 0016）：原样收录，勿手改；同步上游时整文件覆盖。
// 来源：beUI <https://beui.dev/r/number-ticker.json>，上游文件 components/motion/number-ticker.tsx
// 许可证：MIT © 2026 Saurabh Chauhan <https://github.com/starc007/ui-components/blob/main/LICENSE>
// 收录：2026-10-04；适配：落点、import 路径（明细见 vendor.lock.json）
"use client";
// beui.dev/components/motion/number

import { animate, motion, useInView, useReducedMotion } from "motion/react";
import { useEffect, useMemo, useRef, useState } from "react";
import { EASE_OUT } from "@/components/vendor/beui/lib/ease";
import { cn } from "@/lib/utils";

export interface NumberTickerProps {
  value: number;
  /** Digits to pad to (left). */
  pad?: number;
  /** Per-digit roll duration in seconds. */
  duration?: number;
  /** Stagger between digits. */
  stagger?: number;
  /** Render only after the element enters the viewport. */
  startOnView?: boolean;
  prefix?: string;
  suffix?: string;
  /** Add a small blur during digit rolls. */
  blur?: boolean;
  className?: string;
  digitClassName?: string;
  /** Insert locale group separators (commas). Server-component safe. */
  locale?: boolean;
  /** Custom formatter. Client-only — server components must use `locale` instead. */
  format?: (value: number) => string;
}

const DIGIT_HEIGHT_EM = 1.1;
const DIGITS = Array.from({ length: 10 }, (_, n) => n);

export function NumberTicker({
  value,
  pad,
  duration = 0.9,
  stagger = 0.04,
  startOnView = true,
  prefix,
  suffix,
  blur = false,
  className,
  digitClassName,
  locale,
  format,
}: NumberTickerProps) {
  const containerRef = useRef<HTMLSpanElement>(null);
  const inView = useInView(containerRef, { once: true, amount: 0.6 });
  const [armed, setArmed] = useState(!startOnView);

  useEffect(() => {
    if (startOnView && inView) setArmed(true);
  }, [startOnView, inView]);

  const text = useMemo(() => {
    const rounded = Math.round(value);
    const formatted = format
      ? format(rounded)
      : locale
        ? rounded.toLocaleString()
        : rounded.toString();
    return pad ? formatted.padStart(pad, "0") : formatted;
  }, [value, pad, format, locale]);
  const glyphs = useMemo(() => {
    const chars = text.split("");
    // Key by place value (position from the right): a changing digit keeps its
    // identity and rolls to the new value instead of remounting and replaying
    // from 0. Growing numbers add glyphs on the left without re-keying the
    // ones, tens, hundreds already on screen.
    return chars.map((char, i) => ({ char, id: `g-${chars.length - 1 - i}` }));
  }, [text]);
  const readableText = `${prefix ?? ""}${text}${suffix ?? ""}`;

  // Stagger is an entrance flourish. Once the reveal has played, value
  // changes roll every digit immediately — a per-digit delay on live updates
  // reads as lag.
  const [entered, setEntered] = useState(false);
  useEffect(() => {
    if (!armed || entered) return;
    const total = (duration + glyphs.length * stagger) * 1000;
    const t = window.setTimeout(() => setEntered(true), total);
    return () => window.clearTimeout(t);
  }, [armed, entered, duration, stagger, glyphs.length]);

  return (
    <span
      ref={containerRef}
      className={cn("inline-flex items-center tabular-nums", className)}
    >
      <span className="sr-only">{readableText}</span>
      <span aria-hidden="true" className="inline-flex items-center">
        {prefix ? <span>{prefix}</span> : null}
        {glyphs.map(({ char, id }, i) => {
          const isDigit = /\d/.test(char);
          if (!isDigit) {
            return (
              <span key={id} className="inline-block">
                {char}
              </span>
            );
          }
          const digit = Number(char);
          return (
            <Digit
              key={id}
              digit={armed ? digit : 0}
              delay={entered ? 0 : i * stagger}
              duration={duration}
              blur={blur}
              className={digitClassName}
            />
          );
        })}
        {suffix ? <span>{suffix}</span> : null}
      </span>
    </span>
  );
}

function Digit({
  digit,
  delay,
  duration,
  blur,
  className,
}: {
  digit: number;
  delay: number;
  duration: number;
  blur: boolean;
  className?: string;
}) {
  const reduce = useReducedMotion();
  const columnRef = useRef<HTMLSpanElement>(null);

  useEffect(() => {
    if (reduce || !blur || !columnRef.current || !Number.isFinite(digit)) {
      return;
    }

    const node = columnRef.current;
    const controls = animate(
      node,
      { filter: ["blur(10px)", "blur(0px)"] },
      {
        duration: Math.min(duration * 0.75, 0.32),
        delay,
        ease: EASE_OUT,
      },
    );

    return () => {
      controls.stop();
      node.style.filter = "blur(0px)";
    };
  }, [blur, delay, digit, duration, reduce]);

  return (
    <span
      className={cn("relative inline-block overflow-hidden", className)}
      style={{ height: `${DIGIT_HEIGHT_EM}em`, width: "1ch" }}
    >
      <motion.span
        ref={columnRef}
        initial={{ y: 0 }}
        animate={{ y: `-${digit * DIGIT_HEIGHT_EM}em` }}
        transition={
          reduce
            ? { duration: 0 }
            : { duration, delay, ease: EASE_OUT }
        }
        className="absolute inset-x-0 top-0 flex flex-col items-center will-change-[transform,filter]"
      >
        {DIGITS.map((n) => (
          <span
            key={n}
            className="flex h-[1.1em] items-center justify-center leading-none"
          >
            {n}
          </span>
        ))}
      </motion.span>
    </span>
  );
}

// 收录组件 · developstack 设计系统（ADR 0016）：原样收录，勿手改；同步上游时整文件覆盖。
// 来源：beUI <https://beui.dev/r/tooltip.json>，上游文件 components/motion/tooltip.tsx
// 许可证：MIT © 2026 Saurabh Chauhan <https://github.com/starc007/ui-components/blob/main/LICENSE>
// 收录：2026-10-04；适配：落点、import 路径（明细见 vendor.lock.json）
"use client";
// beui.dev/components/motion/tooltip

import { AnimatePresence } from "motion/react";
import { TooltipPositioner } from "./tooltip/positioner";
import { useTooltipPointer } from "./tooltip/use-position";
import {
  cloneElement,
  isValidElement,
  type PointerEvent,
  type ReactElement,
  type ReactNode,
  type RefObject,
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";
import { createPortal } from "react-dom";
import { TooltipSurface } from "@/components/vendor/beui/motion/tooltip-surface";
import { useDismiss } from "@/components/vendor/beui/lib/hooks/use-dismiss";
import { useHoverGesture } from "@/components/vendor/beui/lib/hooks/use-hover-gesture";
import { useTapGesture } from "@/components/vendor/beui/lib/hooks/use-tap-gesture";
import { cn } from "@/lib/utils";

type Side = "top" | "right" | "bottom" | "left";

export interface TooltipProps {
  content: ReactNode;
  children?: ReactElement;
  /** Existing trigger for controlled integrations such as chart cells. */
  anchorRef?: RefObject<HTMLElement | SVGElement | null>;
  /** Point within the anchor, as fractions of its rendered width and height. */
  anchorPoint?: { x: number; y: number };
  /** Follow real pointer coordinates; keyboard focus still uses the anchor. */
  followCursor?: boolean;
  open?: boolean;
  onOpenChange?: (open: boolean) => void;
  id?: string;
  side?: Side;
  /** Delay before showing (ms). Default 120. */
  delay?: number;
  className?: string;
  /** Classes for the outer wrapper span. Use to fix baseline / fill parent. */
  wrapperClassName?: string;
}

// Once any tooltip has just closed, neighbouring tooltips open without the
// initial delay — moving along a toolbar feels instant after the first one.
const WARM_WINDOW_MS = 300;
let lastHiddenAt = 0;

export function Tooltip({
  content,
  children,
  side = "top",
  delay = 120,
  className,
  wrapperClassName,
  anchorRef: externalAnchorRef,
  anchorPoint,
  followCursor = false,
  open: controlledOpen,
  onOpenChange,
  id: providedId,
}: TooltipProps) {
  const [internalOpen, setInternalOpen] = useState(false);
  const open = controlledOpen ?? internalOpen;
  const setOpen = useCallback(
    (next: boolean) => {
      if (controlledOpen === undefined) setInternalOpen(next);
      onOpenChange?.(next);
    },
    [controlledOpen, onOpenChange],
  );
  const generatedId = useId();
  const id = providedId ?? generatedId;
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const wrapperRef = useRef<HTMLSpanElement>(null);
  const anchorRef = externalAnchorRef ?? wrapperRef;
  const hover = useHoverGesture();
  const floatingRef = useRef<HTMLSpanElement | null>(null);
  const pointer = useTooltipPointer(anchorRef, followCursor);
  const focused = useRef(false);

  const show = useCallback(() => {
    if (timer.current) clearTimeout(timer.current);
    if (open) return;
    const warm = Date.now() - lastHiddenAt < WARM_WINDOW_MS;
    if (warm) {
      setOpen(true);
      return;
    }
    timer.current = setTimeout(() => {
      setOpen(true);
    }, delay);
  }, [delay, setOpen, open]);

  const hide = useCallback(() => {
    if (timer.current) {
      clearTimeout(timer.current);
      timer.current = null;
    }
    if (open) lastHiddenAt = Date.now();
    setOpen(false);
  }, [open, setOpen]);

  const leave = useCallback(() => {
    if (focused.current) return;
    if (timer.current) clearTimeout(timer.current);
    // Bridge the small physical gap to a stationary, readable tooltip.
    if (followCursor) hide();
    else timer.current = setTimeout(hide, 100);
  }, [followCursor, hide]);
  const insideTooltip = useCallback(
    (target: Element) => Boolean(floatingRef.current?.contains(target)),
    [],
  );

  // A finger never hovers, and Safari does not focus a button on tap either, so
